-- Track map database (SQLite).  Coordinates are PDF points on the drawing:
-- origin top-left, x to the right, y down, page 6552 x 1440.
-- Everything except access_requests is regenerated by pipeline/build.py.

PRAGMA foreign_keys = ON;

CREATE TABLE tracks (
    id        TEXT PRIMARY KEY,          -- e.g. 'W1', 'C2', 'S1'
    line      TEXT NOT NULL,             -- 'W', 'C', ...
    number    INTEGER NOT NULL,
    from_mp   REAL,
    to_mp     REAL
);

-- A track can be drawn in several disconnected pieces (e.g. C3 is reused
-- for separate third tracks); each piece is a chain of calibrated legs.
CREATE TABLE track_pieces (
    id        INTEGER PRIMARY KEY,
    track_id  TEXT NOT NULL REFERENCES tracks(id),
    from_mp   REAL NOT NULL,
    to_mp     REAL NOT NULL
);

-- One leg runs between two consecutive milepost anchors.  geometry is a JSON
-- array of [x, y] points; mps is a parallel JSON array of milepost values
-- (linear in drawn length between the two anchors).
CREATE TABLE track_legs (
    id        INTEGER PRIMARY KEY,
    piece_id  INTEGER NOT NULL REFERENCES track_pieces(id),
    seq       INTEGER NOT NULL,
    from_mp   REAL NOT NULL,
    to_mp     REAL NOT NULL,
    geometry  TEXT NOT NULL,
    mps       TEXT NOT NULL
);

CREATE TABLE route_anchors (
    track_id   TEXT NOT NULL REFERENCES tracks(id),
    piece_id   INTEGER NOT NULL REFERENCES track_pieces(id),
    mp         REAL NOT NULL,
    x          REAL NOT NULL,
    y          REAL NOT NULL,
    label_id   INTEGER REFERENCES milepost_labels(id),
    line_level INTEGER NOT NULL DEFAULT 0
);

-- Every milepost / interface label read off the drawing.
CREATE TABLE milepost_labels (
    id         INTEGER PRIMARY KEY,
    text       TEXT NOT NULL,            -- as drawn, e.g. '24.39W1'
    mp         REAL,
    suffix     TEXT,                     -- 'W1', 'A2/L2', 'C' (line-level) or NULL (facility)
    kind       TEXT NOT NULL,            -- 'box' | 'oval' (interface location)
    status     TEXT NOT NULL,            -- anchored | line_level | facility | out_of_sequence | unanchored | unused
    confidence REAL,
    x          REAL,                     -- where it attaches to the track network
    y          REAL,
    bbox       TEXT
);

CREATE TABLE stations (
    id    INTEGER PRIMARY KEY,
    name  TEXT NOT NULL,
    x     REAL NOT NULL,
    y     REAL NOT NULL,
    bbox  TEXT
);

-- Track access requests: the operational data.  Preserved across rebuilds.
CREATE TABLE access_requests (
    id          INTEGER PRIMARY KEY,
    request_no  TEXT,
    track_id    TEXT NOT NULL,
    from_mp     REAL NOT NULL,
    to_mp       REAL NOT NULL,
    start_time  TEXT,                    -- ISO 8601
    end_time    TEXT,
    work_type   TEXT,
    requester   TEXT,
    status      TEXT NOT NULL DEFAULT 'requested',   -- requested | approved | active | completed | cancelled
    notes       TEXT,
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    updated_at  TEXT
);

CREATE INDEX idx_requests_track ON access_requests(track_id, from_mp, to_mp);
CREATE INDEX idx_requests_time ON access_requests(start_time, end_time);
CREATE INDEX idx_labels_mp ON milepost_labels(suffix, mp);
